"""Suite-wide rules (E0; frozen -- task branches do not edit this file).

* Network guard: any INET/INET6 socket connect fails the test. Gaia online is
  reached only through an injected ``fetch_text`` stub; there is no live
  VizieR call in this suite, ever.
* Markers ``siril``, ``starnet``, ``ffmpeg``: such tests skip when the tool is
  absent (declared in pyproject.toml). ``perf`` tests run only with
  LOOMSIRIL_PERF=1 (the Docker image sets it). ``vendor`` tests run only with
  LOOMSIRIL_VENDOR=1 (real vendor tools, by hand); ``network`` tests run only
  with LOOMSIRIL_NETWORK=1 (online catalogues, by hand; never in the suite).
* Fixtures: ``synth_field`` (tests/synth.py), ``gaia_tsv_path`` (public IC 1396
  Gaia DR3 table), ``oracle`` (loads tests/oracle/<name>.json recorded from the
  JS by tools/record_oracle.js).
* Files: tests write only under ``tmp_path``.
"""

from __future__ import annotations

import json
import os
import shutil
import socket
from pathlib import Path
from typing import Any, Callable

import pytest

TESTS_DIR = Path(__file__).resolve().parent
FIXTURES_DIR = TESTS_DIR / "fixtures"
ORACLE_DIR = TESTS_DIR / "oracle"


class NetworkBlocked(RuntimeError):
    """Raised when a test tries to open a network connection."""


@pytest.fixture(autouse=True)
def _no_network(monkeypatch: pytest.MonkeyPatch) -> None:
    """Fail any INET/INET6 connection attempt (AF_UNIX stays allowed)."""
    real_connect = socket.socket.connect
    real_connect_ex = socket.socket.connect_ex

    def _guard(sock: socket.socket) -> None:
        if sock.family in (socket.AF_INET, socket.AF_INET6):
            raise NetworkBlocked("network access is not allowed in tests (stub fetch_text instead)")

    def connect(self: socket.socket, address: Any) -> Any:
        _guard(self)
        return real_connect(self, address)

    def connect_ex(self: socket.socket, address: Any) -> Any:
        _guard(self)
        return real_connect_ex(self, address)

    def create_connection(*_a: Any, **_k: Any) -> Any:
        raise NetworkBlocked("network access is not allowed in tests (stub fetch_text instead)")

    monkeypatch.setattr(socket.socket, "connect", connect)
    monkeypatch.setattr(socket.socket, "connect_ex", connect_ex)
    monkeypatch.setattr(socket, "create_connection", create_connection)


def starnet_binary() -> str | None:
    """The StarNet2 CLI to use: $LOOMSIRIL_STARNET if it exists, else starnet2/starnet++ on PATH."""
    env = os.environ.get("LOOMSIRIL_STARNET")
    if env and os.path.isfile(env) and os.access(env, os.X_OK):
        return env
    for name in ("starnet2", "starnet++"):
        found = shutil.which(name)
        if found:
            return found
    return None


def starnet_skip_reason() -> str | None:
    """Why the real-binary StarNet2 tests cannot run here (absent, or older than MIN_STARNET_VERSION), else None."""
    import subprocess

    from loomsiril.starnet_version import starnet_version_problem

    exe = starnet_binary()
    if exe is None:
        return "starnet not available"
    try:
        proc = subprocess.run([exe, "--version"], capture_output=True, text=True, timeout=60, check=False)
    except (OSError, subprocess.SubprocessError):
        return "starnet not available (it did not run)"
    problem = starnet_version_problem((proc.stdout or "").strip().splitlines()[0] if proc.stdout.strip() else "")
    return f"starnet: {problem}" if problem else None


def siril_binary() -> str | None:
    """siril-cli on PATH, if any."""
    return shutil.which("siril-cli")


def pytest_collection_modifyitems(config: pytest.Config, items: list[pytest.Item]) -> None:
    """Skip tests whose tool is absent, with a reason that names the tool."""
    absent = {
        "siril": siril_binary() is None,
        "starnet": starnet_skip_reason(),
        "ffmpeg": shutil.which("ffmpeg") is None,
        # timing budgets run only where asked (the Docker gate), never on a shared dev box
        "perf": os.environ.get("LOOMSIRIL_PERF") != "1",
        "vendor": os.environ.get("LOOMSIRIL_VENDOR") != "1",
        "network": os.environ.get("LOOMSIRIL_NETWORK") != "1",
    }
    for item in items:
        for marker, missing in absent.items():
            if missing and item.get_closest_marker(marker) is not None:  # not item.keywords: it holds folder names too
                item.add_marker(pytest.mark.skip(reason=missing if isinstance(missing, str) else f"{marker} not available"))


@pytest.fixture
def synth_field() -> Callable[..., Any]:
    """Factory: ``synth_field(w=..., h=..., n_stars=..., nc=..., seed=...)`` -> synth.SynthField."""
    import synth

    return synth.make_field


@pytest.fixture(scope="session")
def gaia_tsv_path() -> Path:
    """Public Gaia DR3 sources around IC 1396 (tests/fixtures/README.md)."""
    return FIXTURES_DIR / "ic1396-gaia-g16.tsv"


@pytest.fixture(scope="session")
def oracle() -> Callable[[str], Any]:
    """Loader: ``oracle("geometry")`` -> parsed tests/oracle/geometry.json (skips if not recorded yet)."""

    def load(name: str) -> Any:
        path = ORACLE_DIR / f"{name}.json"
        if not path.exists():
            pytest.skip(f"oracle {path.name} not recorded (run tools/record_oracle.js)")
        with path.open(encoding="utf-8") as fh:
            return json.load(fh, parse_constant=_parse_constant)

    return load


def _parse_constant(name: str) -> float:
    """JSON from the recorder spells non-finite numbers as NaN/Infinity/-Infinity."""
    return {"NaN": float("nan"), "Infinity": float("inf"), "-Infinity": float("-inf")}[name]
